('threshold_tt_8w_w7s4', 't_cp', 7, '6', '5''', 75, 6, 1800, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 108.0, "power_end": 55.0, "duration_work": 300, "duration_recup": 300, "repetitions": 6, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "threshold_tt_8w_lc_start", "duration": 12}, {"at": 1190, "key": "threshold_tt_8w_lc_start", "duration": 12}, {"at": 1790, "key": "threshold_tt_8w_lc_start", "duration": 12}, {"at": 2390, "key": "threshold_tt_8w_lc_start", "duration": 12}, {"at": 2990, "key": "threshold_tt_8w_lc_start", "duration": 12}, {"at": 3590, "key": "threshold_tt_8w_lc_start", "duration": 12}]'::jsonb),
('threshold_tt_8w_w8s1', 't_ss', 8, '2', '15''', 55, 2, 1800, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 90.0, "power_end": 55.0, "duration_work": 900, "duration_recup": 300, "repetitions": 2, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "threshold_tt_8w_lc_start", "duration": 12}, {"at": 1790, "key": "threshold_tt_8w_lc_start", "duration": 12}]'::jsonb),
('threshold_tt_8w_w8s2', 't_thr', 8, '3', '8''', 51, 3, 1440, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 98.0, "power_end": 55.0, "duration_work": 480, "duration_recup": 240, "repetitions": 3, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "threshold_tt_8w_lc_start", "duration": 12}, {"at": 1310, "key": "threshold_tt_8w_lc_start", "duration": 12}, {"at": 2030, "key": "threshold_tt_8w_lc_start", "duration": 12}]'::jsonb),
('threshold_tt_8w_w8s3', 'e_cont', 8, '1', '45''', 60, 1, 2700, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 2700, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "threshold_tt_8w_lc_start", "duration": 12}, {"at": 1950, "key": "threshold_tt_8w_lc_mid", "duration": 12}]'::jsonb)
), built AS (
  SELECT s.*,
    (SELECT jsonb_object_agg(t.lang, wk.p || s.week || ' · ' || replace(replace(replace(replace(t.name, '{n}', s.n), '{d}', s.d), '{m}', s.minutes::text), ' 1×', ' '))
       FROM tpl t JOIN wk USING (lang) WHERE t.typ = s.typ) AS names,
    (SELECT jsonb_object_agg(t.lang, t.obj || ' ' || CASE WHEN s.k = 1 THEN i.one ELSE replace(i.many, '{k}', s.k::text) END)
       FROM tpl t JOIN ind i USING (lang) WHERE t.typ = s.typ) AS objs,
    (SELECT jsonb_object_agg(t.lang, t.info) FROM tpl t WHERE t.typ = s.typ) AS infos
  FROM s
)
INSERT INTO public.training_sessions (name, info, objectif, session_json, total_duration, is_test, live_comments, translations_json, aero_duration_sec)
SELECT b.skey || '_name', b.skey || '_info', b.skey || '_objectif',
  jsonb_build_object('nom', b.names ->> 'fr', 'infos', '', 'duration', b.minutes, 'UnitDisplay', '% FTP', 'blocks', b.blocks),
  b.minutes, false, b.lc,
  jsonb_build_object('name', b.names, 'objectif', b.objs, 'info', b.infos, 'live_comments', '{"threshold_tt_8w_lc_start": {"fr": "Passe en TT sur les prolongateurs : épaules relâchées, tiens jusqu''au bout du bloc.", "en": "Get into TT on the extensions: shoulders relaxed, hold until the end of the block.", "es": "Ponte en TT en los acoples: hombros relajados, aguanta hasta el final del bloque.", "it": "Mettiti in TT sulle protesi: spalle rilassate, tieni fino alla fine del blocco.", "de": "Ab in TT auf den Aufsatz: Schultern locker, bis zum Ende des Blocks halten.", "nl": "Ga in TT op de opzetstukken: schouders ontspannen, houd vol tot het einde van het blok.", "pt": "Vá para o TT no clipe: ombros relaxados, aguente até o fim do bloco.", "ja": "エアロバーでTTに：肩の力を抜き、ブロックの最後まで維持しよう。", "tr": "Uzatmalarda TT''ye geç: omuzlar gevşek, blok bitene kadar koru."}, "threshold_tt_8w_lc_up": {"fr": "Relève-toi et récupère. Prochain bloc en TT.", "en": "Sit up and recover. Next block in TT.", "es": "Incorpórate y recupera. Próximo bloque en TT.", "it": "Rialzati e recupera. Prossimo blocco in TT.", "de": "Aufrichten und erholen. Nächster Block in TT.", "nl": "Kom overeind en herstel. Volgend blok in TT.", "pt": "Levante o tronco e recupere. Próximo bloco em TT.", "ja": "上体を起こして回復。次のブロックはTTで。", "tr": "Doğrul ve toparlan. Sonraki blok TT''de."}, "threshold_tt_8w_lc_mid": {"fr": "Mi-bloc : vérifie ta tête et tes épaules, reste bas et relâché.", "en": "Halfway: check your head and shoulders, stay low and relaxed.", "es": "Mitad del bloque: revisa cabeza y hombros, sigue abajo y relajado.", "it": "Metà blocco: controlla testa e spalle, resta basso e rilassato.", "de": "Halbzeit: Kopf und Schultern prüfen, tief und locker bleiben.", "nl": "Halverwege: check je hoofd en schouders, blijf laag en ontspannen.", "pt": "Metade do bloco: confira cabeça e ombros, fique baixo e relaxado.", "ja": "ブロックの半分：頭と肩を確認、低くリラックスしたまま。", "tr": "Blok ortası: başını ve omuzlarını kontrol et, alçak ve gevşek kal."}, "threshold_tt_8w_lc_recup": {"fr": "Récupère en TT : reste sur les prolongateurs, ton cerveau associe la position au repos.", "en": "Recover in TT: stay on the extensions, your brain links the position with rest.", "es": "Recupera en TT: sigue en los acoples, tu cerebro asocia la posición al descanso.", "it": "Recupera in TT: resta sulle protesi, il cervello associa la posizione al riposo.", "de": "Erhole dich in TT: Bleib auf dem Aufsatz, dein Gehirn verbindet die Position mit Ruhe.", "nl": "Herstel in TT: blijf op de opzetstukken, je brein koppelt de houding aan rust.", "pt": "Recupere em TT: fique no clipe, seu cérebro associa a posição ao descanso.", "ja": "TTで回復：エアロバーに乗ったまま。脳がこの姿勢を休息と結びつけます。", "tr": "TT''de toparlan: uzatmalarda kal, beynin pozisyonu dinlenmeyle ilişkilendirir."}}'::jsonb),
  b.aero
FROM built b
WHERE NOT EXISTS (SELECT 1 FROM public.training_sessions ts WHERE ts.name = b.skey || '_name');

INSERT INTO public.training_plans (name_key, description_key, objective_key, duration_weeks, difficulty, plan_type, sessions_per_week, is_active, translations_json)
SELECT 'threshold_tt_8w_name', 'threshold_tt_8w_description', 'threshold_tt_8w_objective', 8, 'advanced', 'training', 4, true, '{"name": {"fr": "Seuil et puissance critique en aéro 8 semaines", "en": "8-week threshold and critical power in aero", "es": "Umbral y potencia crítica en aero 8 semanas", "it": "Soglia e potenza critica in aero 8 settimane", "de": "8 Wochen Schwelle und kritische Leistung in Aero", "nl": "8 weken drempel en kritisch vermogen in aero", "pt": "Limiar e potência crítica em aero 8 semanas", "ja": "8週間エアロでの閾値とクリティカルパワー", "tr": "8 haftalık aero''da eşik ve kritik güç"}, "objective": {"fr": "Produire ta FTP et ta puissance critique en position TT : jusqu''à 3×20'' au seuil et 6×5'' à 108 % FTP en TT.", "en": "Produce your FTP and critical power in the TT position: up to 3×20'' at threshold and 6×5'' at 108% FTP in TT.", "es": "Producir tu FTP y tu potencia crítica en posición TT: hasta 3×20'' en el umbral y 6×5'' al 108 % FTP en TT.", "it": "Produrre FTP e potenza critica in posizione TT: fino a 3×20'' alla soglia e 6×5'' al 108 % FTP in TT.", "de": "FTP und kritische Leistung in TT-Position erbringen: bis zu 3×20'' an der Schwelle und 6×5'' bei 108 % FTP in TT.", "nl": "Je FTP en kritisch vermogen in TT-houding leveren: tot 3×20'' op drempel en 6×5'' op 108 % FTP in TT.", "pt": "Produzir sua FTP e potência crítica na posição TT: até 3×20'' no limiar e 6×5'' a 108 % FTP em TT.", "ja": "TTポジションでFTPとクリティカルパワーを発揮：閾値で最大3×20''、108 % FTPで6×5''。", "tr": "FTP''ni ve kritik gücünü TT pozisyonunda üret: eşikte 3×20''e ve %108 FTP''de 6×5''e kadar TT''de."}, "description": {"fr": "8 semaines, deux cycles de 3 semaines de charge et 1 allégée, 3 à 4 séances de 50 à 110 minutes, tous les efforts en TT : sweet spot de 12 à 30 minutes, seuil de 6 à 20 minutes, sur-sous et puissance critique de 3 à 5 minutes.", "en": "8 weeks, two cycles of 3 loading weeks and 1 lighter week, 3 to 4 sessions of 50 to 110 minutes, all efforts in TT: sweet spot from 12 to 30 minutes, threshold from 6 to 20 minutes, over-unders and critical power from 3 to 5 minutes.", "es": "8 semanas, dos ciclos de 3 semanas de carga y 1 más ligera, 3 a 4 sesiones de 50 a 110 minutos, todos los esfuerzos en TT: sweet spot de 12 a 30 minutos, umbral de 6 a 20 minutos, sobre-bajo y potencia crítica de 3 a 5 minutos.", "it": "8 settimane, due cicli di 3 settimane di carico e 1 di scarico, da 3 a 4 sessioni da 50 a 110 minuti, tutti gli sforzi in TT: sweet spot da 12 a 30 minuti, soglia da 6 a 20 minuti, sopra-sotto e potenza critica da 3 a 5 minuti.", "de": "8 Wochen, zwei Zyklen aus 3 Belastungswochen und 1 Entlastungswoche, 3 bis 4 Einheiten von 50 bis 110 Minuten, alle Belastungen in TT: Sweet Spot von 12 bis 30 Minuten, Schwelle von 6 bis 20 Minuten, Over-Under und kritische Leistung von 3 bis 5 Minuten.", "nl": "8 weken, twee cycli van 3 belastingsweken en 1 lichtere week, 3 tot 4 sessies van 50 tot 110 minuten, alle inspanningen in TT: sweet spot van 12 tot 30 minuten, drempel van 6 tot 20 minuten, over-unders en kritisch vermogen van 3 tot 5 minuten.", "pt": "8 semanas, dois ciclos de 3 semanas de carga e 1 mais leve, 3 a 4 sessões de 50 a 110 minutos, todos os esforços em TT: sweet spot de 12 a 30 minutos, limiar de 6 a 20 minutos, acima-abaixo e potência crítica de 3 a 5 minutos.", "ja": "8週間、負荷3週＋軽め1週の2サイクル、50〜110分のセッションを週3〜4回、全ての努力をTTで：スイートスポット12〜30分、閾値6〜20分、オーバーアンダーとクリティカルパワー3〜5分。", "tr": "8 hafta, 3 yüklenme + 1 hafif haftadan oluşan iki döngü, haftada 50-110 dakikalık 3-4 seans, tüm eforlar TT''de: 12-30 dakika sweet spot, 6-20 dakika eşik, 3-5 dakika üst-alt ve kritik güç."}}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.training_plans WHERE name_key = 'threshold_tt_8w_name');

INSERT INTO public.plan_sessions (plan_id, training_session_id, week_number, session_number)
SELECT p.id, ts.id, v.week, v.num
FROM (VALUES (1, 1, 'threshold_tt_8w_w1s1_name'), (1, 2, 'threshold_tt_8w_w1s2_name'), (1, 3, 'threshold_tt_8w_w1s3_name'), (1, 4, 'threshold_tt_8w_w1s4_name'), (2, 1, 'threshold_tt_8w_w2s1_name'), (2, 2, 'threshold_tt_8w_w2s2_name'), (2, 3, 'threshold_tt_8w_w2s3_name'), (2, 4, 'threshold_tt_8w_w2s4_name'), (3, 1, 'threshold_tt_8w_w3s1_name'), (3, 2, 'threshold_tt_8w_w3s2_name'), (3, 3, 'threshold_tt_8w_w3s3_name'), (3, 4, 'threshold_tt_8w_w3s4_name'), (4, 1, 'threshold_tt_8w_w4s1_name'), (4, 2, 'threshold_tt_8w_w4s2_name'), (4, 3, 'threshold_tt_8w_w4s3_name'), (5, 1, 'threshold_tt_8w_w5s1_name'), (5, 2, 'threshold_tt_8w_w5s2_name'), (5, 3, 'threshold_tt_8w_w5s3_name'), (5, 4, 'threshold_tt_8w_w5s4_name'), (6, 1, 'threshold_tt_8w_w6s1_name'), (6, 2, 'threshold_tt_8w_w6s2_name'), (6, 3, 'threshold_tt_8w_w6s3_name'), (6, 4, 'threshold_tt_8w_w6s4_name'), (7, 1, 'threshold_tt_8w_w7s1_name'), (7, 2, 'threshold_tt_8w_w7s2_name'), (7, 3, 'threshold_tt_8w_w7s3_name'), (7, 4, 'threshold_tt_8w_w7s4_name'), (8, 1, 'threshold_tt_8w_w8s1_name'), (8, 2, 'threshold_tt_8w_w8s2_name'), (8, 3, 'threshold_tt_8w_w8s3_name')) AS v(week, num, session_name)
JOIN public.training_sessions ts ON ts.name = v.session_name
JOIN public.training_plans p ON p.name_key = 'threshold_tt_8w_name'
WHERE NOT EXISTS (SELECT 1 FROM public.plan_sessions ps WHERE ps.plan_id = p.id AND ps.training_session_id = ts.id);
